136	/**
137	 * Sanitizes an array of paths by deduplicating them and ensuring they are absolute.
138	 */
139	export function sanitizePaths(paths?: string[]): string[] | undefined {
140	  if (!paths) return undefined;
141	
142	  // We use a Map to deduplicate paths based on their normalized,
143	  // platform-specific identity e.g. handling case-insensitivity on Windows)
144	  // while preserving the original string casing.
145	  const uniquePathsMap = new Map<string, string>();
146	  for (const p of paths) {
147	    if (!path.isAbsolute(p)) {
148	      throw new Error(`Sandbox path must be absolute: ${p}`);
149	    }
150	
151	    // Normalize the path (resolves slashes and redundant components)
152	    let key = path.normalize(p);
153	
154	    // Windows file systems are case-insensitive, so we lowercase the key for
155	    // deduplication
156	    if (os.platform() === 'win32') {
157	      key = key.toLowerCase();
158	    }
159	
160	    if (!uniquePathsMap.has(key)) {
161	      uniquePathsMap.set(key, p);
162	    }
163	  }
164	
165	  return Array.from(uniquePathsMap.values());
166	}
