100	/**
101	 * A SandboxManager implementation for Linux that uses Bubblewrap (bwrap).
102	 */
103	export class LinuxSandboxManager implements SandboxManager {
104	  constructor(private readonly options: GlobalSandboxOptions) {}
105	
106	  async prepareCommand(req: SandboxRequest): Promise<SandboxedCommand> {
107	    const sanitizationConfig = getSecureSanitizationConfig(
108	      req.policy?.sanitizationConfig,
109	    );
110	
111	    const sanitizedEnv = sanitizeEnvironment(req.env, sanitizationConfig);
112	
113	    const bwrapArgs: string[] = [
114	      '--unshare-all',
115	      '--new-session', // Isolate session
116	      '--die-with-parent', // Prevent orphaned runaway processes
117	      '--ro-bind',
118	      '/',
119	      '/',
120	      '--dev', // Creates a safe, minimal /dev (replaces --dev-bind)
121	      '/dev',
122	      '--proc', // Creates a fresh procfs for the unshared PID namespace
123	      '/proc',
124	      '--tmpfs', // Provides an isolated, writable /tmp directory
125	      '/tmp',
126	      // Note: --dev /dev sets up /dev/pts automatically
127	      '--bind',
128	      this.options.workspace,
129	      this.options.workspace,
130	    ];
131	
132	    // Protected governance files are bind-mounted as read-only, even if the workspace is RW.
133	    // We ensure they exist on the host and resolve real paths to prevent symlink bypasses.
134	    // In bwrap, later binds override earlier ones for the same path.
135	    for (const file of GOVERNANCE_FILES) {
136	      const filePath = join(this.options.workspace, file.path);
137	      touch(filePath, file.isDirectory);
138	
139	      const realPath = fs.realpathSync(filePath);
140	
141	      bwrapArgs.push('--ro-bind', filePath, filePath);
142	      if (realPath !== filePath) {
143	        bwrapArgs.push('--ro-bind', realPath, realPath);
144	      }
145	    }
146	
147	    const allowedPaths = sanitizePaths(req.policy?.allowedPaths) || [];
148	    const normalizedWorkspace = normalize(this.options.workspace).replace(
149	      /\/$/,
150	      '',
151	    );
152	    for (const allowedPath of allowedPaths) {
153	      const normalizedAllowedPath = normalize(allowedPath).replace(/\/$/, '');
154	      if (normalizedAllowedPath !== normalizedWorkspace) {
155	        bwrapArgs.push('--bind-try', allowedPath, allowedPath);
156	      }
157	    }
158	
159	    // TODO: handle forbidden paths
160	
161	    const bpfPath = getSeccompBpfPath();
162	
163	    bwrapArgs.push('--seccomp', '9');
164	    bwrapArgs.push('--', req.command, ...req.args);
165	
166	    const shArgs = [
167	      '-c',
168	      'bpf_path="$1"; shift; exec bwrap "$@" 9< "$bpf_path"',
169	      '_',
170	      bpfPath,
171	      ...bwrapArgs,
172	    ];
173	
174	    return {
175	      program: 'sh',
176	      args: shArgs,
177	      env: sanitizedEnv,
178	    };
179	  }
